<script setup lang="ts">import {Link} from '@inertiajs/vue3';import {computed} from 'vue';import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import EmptyState from '@/Components/EmptyState.vue';import type {Setting} from '@/types';const props=defineProps<{settings:Setting[]}>();const labels:Record<string,string>={'verification.require_identity_last4':'Exigir verificación de identidad','verification.show_patient_name':'Mostrar paciente enmascarado','verification.show_diagnosis':'Mostrar diagnóstico','privacy.public_doctor_credentials':'Mostrar credencial del médico'};const websiteSettings=computed(()=>props.settings.filter(item=>item.key in labels));</script>
<template><AdminLayout title="Configuración" eyebrow="Sistema"><PageMeta title="Configuración" noindex/><section class="admin-content narrow-content"><div class="content-toolbar"><div><p class="kicker">Parámetros</p><h2>Configuración institucional</h2></div><span class="privacy-chip">Valores autorizados</span></div><div v-if="websiteSettings.length" class="settings-list"><div v-for="item in websiteSettings" :key="item.id" class="panel setting-row"><div><code class="code-wrap">{{ item.key }}</code><p>{{ labels[item.key] }}</p></div><strong>{{ item.value?'Sí':'No' }}</strong><Link class="row-action" :href="route('admin.settings.edit',item.id)">Editar</Link></div></div><EmptyState v-else title="No hay parámetros configurados"/></section></AdminLayout></template>
